const capsules = [
  {id:1,cat:'base',title:'Rol y límites de primera línea',summary:'Atender, comprender, coordinar e informar sin asumir decisiones técnicas.',flow:['Recibir','Comprender','Actuar o escalar','Informar','Cerrar'],objective:'Distinguir atención, resolución y coordinación, y saber qué puede afirmar ante el cliente.',case:'Un ticket no urgente se escala a un técnico ocupado. Se registra como pendiente de análisis, con responsable, próxima revisión y fecha de actualización al cliente.',checks:['¿Qué puede resolver sin validación?','¿Qué debe confirmar antes de prometer?','¿Cuándo un ticket requiere seguimiento aunque no sea urgente?'],limits:'No confirmar causas, plazos, viabilidad, costes ni autorizaciones sin validación.'},
  {id:2,cat:'base',title:'Interpretación y triaje de tickets',summary:'Separar hechos, suposiciones, datos faltantes, impacto y urgencia.',flow:['Objetivo del cliente','Paso donde falla','Datos y evidencia','Impacto','Prioridad'],objective:'Transformar mensajes incompletos en un resumen accionable.',case:'“No puedo abonar parcialmente una factura desde tráfico”. Primero se aclara si “abonar” significa pagar o emitir un abono, y se piden factura, expediente, importe, paso y captura.',checks:['Explícalo con tus palabras.','¿Qué sabes y qué estás suponiendo?','¿Qué dato cambiaría la prioridad?'],limits:'Urgente no significa “el cliente insiste”; implica bloqueo, impacto o compromiso operativo inmediato.'},
  {id:3,cat:'base',title:'Base de conocimiento viva',summary:'Convertir casos resueltos en fichas breves, buscables y validadas.',flow:['Caso real','Borrador de ficha','Validación técnica','Publicación','Revisión'],objective:'Evitar que una explicación se pierda y reutilizarla con seguridad.',case:'Ficha: señales para reconocer el caso, datos que pedir, comprobaciones, solución confirmada, límites, escalado, respuesta y enlace a Zendesk.',checks:['¿La solución está confirmada o es provisional?','¿Puede otra persona aplicar la ficha?','¿Indica cuándo no debe usarse?'],limits:'La persona de soporte propone; un técnico valida causas y soluciones técnicas.'},
  {id:4,cat:'operativa',title:'Tráfico y recorrido del expediente',summary:'Comprender el flujo operativo y cómo un dato anterior afecta procesos posteriores.',flow:['Previsión','Expediente','Booking / transporte','Documentos','Facturación','Cierre'],objective:'Leer un problema dentro del recorrido completo, no como una pantalla aislada.',case:'Para una incidencia al cerrar expediente: pedir referencia, mensaje, paso exacto y comprobar si bloquea una operación o afecta a varios usuarios.',checks:['¿Dónde comienza la tarea?','¿Qué dato previo la alimenta?','¿Qué proceso posterior queda afectado?'],limits:'No cambiar datos operativos para “probar” sin autorización ni trazabilidad.'},
  {id:5,cat:'operativa',title:'Integraciones y APIs',summary:'Identificar origen, destino, dirección de los datos y respuesta externa.',flow:['Sistema origen','Envío o consulta','Plataforma externa','Confirmación o rechazo','Registro'],objective:'Recoger el contexto correcto sin necesitar diagnosticar formatos técnicos.',case:'Booking: se prepara en DeiWorld, se envía, vuelve una confirmación o error y se consulta su estado. Registrar referencia, momento, respuesta y alcance.',checks:['¿Se envía o se recibe?','¿Es consulta u operación?','¿Existe acuse, rechazo o silencio?'],limits:'No interpretar un error externo como causa confirmada hasta revisar mensajes y trazas.'},
  {id:6,cat:'operativa',title:'Tarifas, cotización y previsión',summary:'Seguir el dato desde navieras o Excel hasta la operación aceptada.',flow:['Tarifa','Validación','Cotización','Aceptación','Previsión operativa'],objective:'Localizar en qué tramo se rompe el flujo comercial-operativo.',case:'La IA lee un Excel de naviera. Antes de cotizar deben revisarse datos dudosos: ruta, vigencia, moneda, conceptos y condiciones.',checks:['¿De dónde procede la tarifa?','¿Está vigente y validada?','¿La cotización aceptada generó la previsión?'],limits:'No usar ni confirmar una tarifa dudosa; escalar con archivo, naviera, ruta, vigencia y cotización.'},
  {id:7,cat:'operativa',title:'Track & Trace y comunicación',summary:'Interpretar lo que ve el cliente en marítimo, aéreo, terrestre y tren.',flow:['Operación','Datos visibles','Evento','Actualización','Aviso al cliente'],objective:'Diferenciar estado mostrado, fuente del evento y confirmación real.',case:'El cliente no ve una expedición o un evento parece atrasado. Localizar expediente, dato faltante, última actualización y origen automático o manual.',checks:['¿Qué ve exactamente el cliente?','¿Cuándo y desde dónde se actualizó?','¿Es un dato o una confirmación operativa?'],limits:'No presentar un evento pendiente o estimado como hecho confirmado.'},
  {id:8,cat:'comercial',title:'CRM: de la acción al resultado',summary:'Relacionar cliente, actividad, campaña, cotización, operación y profit.',flow:['Cliente y potencial','Acción','Campaña','Cotización','Operación','Resultado'],objective:'Entender cómo se mide el esfuerzo comercial y su rendimiento real.',case:'Campaña para captar tráfico FCL: reunión, necesidad detectada, oferta, operación y profit acumulado, manteniendo el criterio de atribución.',checks:['¿Qué información relevante dejó la acción?','¿Qué siguiente paso existe?','¿Por qué la operación se atribuye a esa campaña?'],limits:'No confundir potencial comercial con tráfico confirmado ni profit previsto con real.'},
  {id:9,cat:'base',title:'Gestor de modificaciones',summary:'Reconstruir qué campo cambió, de qué valor a cuál, quién y cuándo.',flow:['Registro afectado','Intervalo','Campo y valores','Usuario o proceso','Hipótesis'],objective:'Investigar hechos trazables sin convertir correlaciones en explicaciones.',case:'Cambió una fecha de entrega: comprobar valor anterior, nuevo valor, fecha/hora y usuario o proceso que lo actualizó.',checks:['¿El historial registra este tipo de cambio?','¿Quién o qué proceso aparece?','¿El motivo está confirmado o inferido?'],limits:'El historial demuestra el cambio, no necesariamente su motivo. No atribuir culpa.'},
  {id:10,cat:'finanzas',title:'Facturación, contabilidad y riesgo',summary:'Seguir la factura desde tráfico y comprender diario, cartera, asiento y crédito.',flow:['Factura desde tráfico','Serie','Diario y asiento','Cartera','Riesgo','Bloqueo o autorización'],objective:'Relacionar el hecho operativo con su efecto contable y de riesgo.',case:'Una nueva operación supera el crédito considerando cartera activa y envíos. El sistema bloquea por tramo hasta autorización responsable.',checks:['¿Qué entra en el cálculo de riesgo?','¿Qué aviso se muestra?','¿Quién puede desbloquear o cambiar límites?'],limits:'Soporte recopila y explica el estado; no autoriza riesgo, cambia crédito ni altera asientos.'},
  {id:11,cat:'finanzas',title:'Cobros, remesas y reclamaciones',summary:'Desde el vencimiento hasta el saldo, conciliación o reclamación.',flow:['Factura y vencimiento','Forma de cobro','Remesa o transferencia','Aplicación','Saldo','Reclamación'],objective:'Distinguir generación, envío bancario, respuesta y aplicación del cobro.',case:'Practicar cobros parciales, múltiples y compensaciones cliente-proveedor; separar tres niveles de carta, estado de cuenta y operaciones activas.',checks:['¿Qué facturas e importes intervienen?','¿El problema está en remesa, banco o aplicación?','¿Qué se comunicó y cuándo?'],limits:'No modificar saldos, detener reclamaciones, compensar ni acordar aplazamientos sin autorización.'},
  {id:12,cat:'gestion',title:'Cartera de desarrollos',summary:'Hacer visible fase, hitos, bloqueos, decisiones y próxima acción.',flow:['Petición','Análisis','Valoración','Decisión','Planificación','Desarrollo','Pruebas','Entrega'],objective:'Mantener el control de desarrollos largos sin duplicar la conversación de Zendesk.',case:'Un desarrollo encallado pasa a “bloqueado” con causa, siguiente paso, dependencia y fecha de revisión; el cliente recibe una actualización prudente.',checks:['¿Cuál es la fase real?','¿Qué impide avanzar?','¿Quién debe hacer qué y cuándo se revisa?'],limits:'Limitar trabajo en curso. La coordinadora actualiza fases cuando el responsable lo confirma.'},
  {id:13,cat:'gestion',title:'Coordinación de proyectos y aduanas',summary:'Ordenar reuniones y decisiones; abordar aduanas con especial prudencia.',flow:['Objetivo y agenda','Decisiones','Tareas y responsables','Bloqueos','Seguimiento'],objective:'Coordinar proyectos pequeños y recopilar correctamente incidencias aduaneras.',case:'Tras una reunión: acuerdos, responsable, fecha y decisión pendiente. En un DUA: expediente, tipo de declaración, referencia, estado, mensaje oficial y evidencia.',checks:['¿Qué decisión se tomó y quién la aprobó?','¿Qué tarea tiene responsable y fecha?','En aduanas, qué dato es del ERP y cuál de la administración?'],limits:'No interpretar normativa, alterar declaraciones ni confirmar aceptación aduanera sin validación especializada.'}
];

const state={filter:'all',query:'',done:new Set(JSON.parse(localStorage.getItem('dw-training-done')||'[]'))};
const grid=document.querySelector('#capsuleGrid'),dialog=document.querySelector('#capsuleDialog'),dialogContent=document.querySelector('#dialogContent');
const labels={base:'Base',operativa:'Operativa',comercial:'Comercial',finanzas:'Finanzas',gestion:'Gestión'};
function render(){const q=state.query.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');const visible=capsules.filter(c=>(state.filter==='all'||c.cat===state.filter)&&(`${c.title} ${c.summary} ${c.objective} ${c.case}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q)));grid.innerHTML=visible.map(c=>`<article class="capsule-card"><div class="capsule-top"><span class="capsule-number">CÁPSULA ${String(c.id).padStart(2,'0')}</span><span class="tag">${labels[c.cat]}</span></div><h3>${c.title}</h3><p>${c.summary}</p><div class="capsule-footer"><button class="open-capsule" data-open="${c.id}">Abrir cápsula</button><label class="check-label"><input type="checkbox" data-done="${c.id}" ${state.done.has(c.id)?'checked':''}> Consolidada</label></div></article>`).join('');document.querySelector('#emptyState').hidden=visible.length>0;updateProgress()}
function updateProgress(){const n=state.done.size,p=Math.round(n/capsules.length*100);document.querySelector('#progressRing').style.setProperty('--p',p);document.querySelector('#progressPercent').textContent=`${p}%`;document.querySelector('#progressText').textContent=`${n} de ${capsules.length} cápsulas`}
function openCapsule(id){const c=capsules.find(x=>x.id===id);dialogContent.innerHTML=`<div class="dialog-body"><span class="eyebrow">Cápsula ${String(c.id).padStart(2,'0')} · ${labels[c.cat]}</span><h2 id="dialogTitle">${c.title}</h2><p class="lead">${c.summary}</p><div class="dialog-sections"><section class="dialog-section"><h3>Objetivo</h3><p>${c.objective}</p></section><section class="dialog-section"><h3>Flujo mental</h3><div class="flow">${c.flow.map(x=>`<span>${x}</span>`).join('')}</div></section><section class="dialog-section"><h3>Caso práctico</h3><p>${c.case}</p></section><section class="dialog-section"><h3>Comprobación de comprensión</h3><ul>${c.checks.map(x=>`<li>${x}</li>`).join('')}</ul></section><section class="dialog-section"><h3>Límite de autonomía</h3><p>${c.limits}</p></section></div></div>`;dialog.showModal()}
grid.addEventListener('click',e=>{const open=e.target.closest('[data-open]');if(open)openCapsule(Number(open.dataset.open));});
grid.addEventListener('change',e=>{if(!e.target.matches('[data-done]'))return;const id=Number(e.target.dataset.done);e.target.checked?state.done.add(id):state.done.delete(id);localStorage.setItem('dw-training-done',JSON.stringify([...state.done]));updateProgress()});
document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.filter=b.dataset.filter;render()}));
document.querySelector('#searchInput').addEventListener('input',e=>{state.query=e.target.value;render()});
document.querySelector('#dialogClose').addEventListener('click',()=>dialog.close());
document.querySelector('#resetProgress').addEventListener('click',()=>{if(confirm('¿Quieres reiniciar todo el progreso de formación?')){state.done.clear();localStorage.removeItem('dw-training-done');render()}});
document.querySelectorAll('.copy-button').forEach(b=>b.addEventListener('click',async()=>{await navigator.clipboard.writeText(b.dataset.copy);const t=document.querySelector('#toast');t.textContent='Plantilla copiada';t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1700)}));
const menu=document.querySelector('#menuButton'),sidebar=document.querySelector('#sidebar');menu.addEventListener('click',()=>{const open=sidebar.classList.toggle('open');menu.setAttribute('aria-expanded',open)});document.querySelectorAll('.nav-link').forEach(a=>a.addEventListener('click',()=>{sidebar.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
render();
